def build_nouns_daily_bundle(existing_norms: set[str]):
    entries = []
    seen = set()
    rank = 1

    all_data = RAW_DAILY + RAW_FOOD + RAW_CLOTHES

    for row in all_data:
        headword = row[0]
        norm = norm_vocab(headword)
        if norm in existing_norms or norm in seen:
            continue
        seen.add(norm)

        gender = row[1]
        level = row[2]
        msa = row[3]
        eg = row[4]
        domain = row[5]
        ex_es = row[6]
        ex_ar = row[7]

        entry = make_noun(headword, gender, level, msa, eg, ex_es, ex_ar, domain=domain, rank=rank)
        entries.append(entry)
        rank += 1

    emit_bundle(
        filename="vocab-cv-nouns-daily.json",
        bundle_slug="cv-nouns-daily",
        title_ar="أسماء الحياة اليومية والمنزل والطعام والأزياء",
        entries=entries
    )
    return len(entries), seen

if __name__ == "__main__":
    count, _ = build_nouns_daily_bundle(get_existing_norms())
    print(f"Generated {count} entries in vocab-cv-nouns-daily.json")
